Arguments: {"title":"Inspect Show filters button","cwd":null,"code":"const tabId = 248688707;
const btnDetails = await browserjs(tabId, () => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show filters'));
  if (!btn) return null;
  const rect = btn.getBoundingClientRect();
  return {
    outerHTML: btn.outerHTML,
    rect: { top: rect.top, left: rect.left, width: rect.width, height: rect.height },
    visible: rect.width > 0 && rect.height > 0
  };
});
console.log(btnDetails);
"}
